def choose_move(observation):
    w, h = observation['grid_width'], observation['grid_height']
    x, y = observation['self_position']
    opp_x, opp_y = observation['opponent_position']
    resources = observation['resources']
    obstacles = set(observation.get('obstacles', []))
    def dist(a, b): return abs(a[0]-b[0]) + abs(a[1]-b[1])
    target = None
    min_d = float('inf')
    for res in resources:
        res_pos = res
        d = dist((x,y), res_pos)
        if d < min_d:
            min_d = d
            target = res_pos
    def move_towards(t):
        dx = dy = 0
        if t[0] > x: dx=1
        elif t[0]<x: dx=-1
        if t[1] > y: dy=1
        elif t[1]< y: dy=-1
        # Avoid obstacles
        new_x, new_y = x+dx, y+dy
        if (0<=new_x<w and 0<=new_y<h and (new_x,new_y) not in obstacles):
            return dx, dy
        # Try alternative directions
        for ddx, ddy in [(0,1),(0,-1),(1,0),(-1,0)]:
            nx, ny = x+ddx, y+ddy
            if (0<=nx<w and 0<=ny<h and (nx,ny) not in obstacles):
                return ddx, ddy
        return 0,0
    if target:
        return move_towards(target)
    else:
        # No resources, move towards opponent
        return move_towards((opp_x, opp_y))
